.mv4.is-ph{height:auto;min-height:100svh}
.mv4.is-ph .mv4-in{min-height:100svh;padding-top:96px;padding-bottom:32px;gap:0}
.mv4.is-ph .mv4-top{flex-direction:column;gap:8px;font-size:12px} .mv4.is-ph .mv4-note{display:none}
.mv4.is-ph .mv4-band{top:34%} .mv4.is-ph .mv4-fr{width:168px;padding:0 6px} .mv4.is-ph .mv4-holes{height:22px} .mv4.is-ph .mv4-holes b{width:10px;height:7px} .mv4.is-ph .mv4-fr em{font-size:12px;bottom:0}
