.mv-fill{position:absolute;z-index:0;inset:0;background:var(--fill);border-radius:inherit;clip-path:inset(0 100% 0 0);transition:clip-path .6s cubic-bezier(.7,0,.2,1)} .mv-btn:hover .mv-fill,.mv-btn:focus-visible .mv-fill{clip-path:inset(0 0 0 0)}
.mv-lbl{position:relative;z-index:1;display:inline-flex;flex-direction:column;justify-content:center;line-height:1.15}
.mv-roll{display:block;height:1.2em;overflow:hidden;line-height:1.2} .mv-l1,.mv-l2{display:block;transition:translate .5s cubic-bezier(.7,0,.2,1)} .mv-btn:hover .mv-l1,.mv-btn:hover .mv-l2,.mv-btn:focus-visible .mv-l1,.mv-btn:focus-visible .mv-l2{translate:0 -100%}
