.mvli-card{--e:1;--hit:0} .mvli.is-anim:not(.is-on) .mvli-card{opacity:0} .mvli.is-anim.is-on .mvli-card{animation:mvli-in .8s cubic-bezier(.2,.8,.2,1) both;animation-delay:calc(var(--i) * 70ms)}
