.mvli-band{background:none;-webkit-mask:none;mask:none} .mvli-band::before{content:"";position:absolute;inset:0;background:color-mix(in srgb,var(--mv-pine) 70%,#000);-webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='24' height='22'><rect x='6' y='5' width='12' height='12' rx='2.5'/></svg>") 6px 0/24px 22px repeat-x;mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='24' height='22'><rect x='6' y='5' width='12' height='12' rx='2.5'/></svg>") 6px 0/24px 22px repeat-x}
