.mvwi-meter{position:absolute;right:clamp(12px,1.6vw,22px);top:12px;display:grid;grid-template-columns:auto auto;align-items:baseline;column-gap:14px;row-gap:7px;padding:9px 12px 10px;border-radius:8px;background:#0E0D0C;-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--mv-cloud) 16%,transparent);font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--mv-mut)}
