.mvwi-cols{position:relative;z-index:2;display:grid;grid-template-columns:minmax(0,7fr) minmax(0,5fr);gap:clamp(14px,1.8vw,26px);align-items:stretch}
.mvwi-col{position:relative;display:flex;flex-direction:column;gap:10px;padding:14px var(--lane);background:#0E0D0C;border-radius:2px;box-shadow:0 12px 26px -12px rgba(60,40,10,.55)}
.mvwi-col.is-c1{margin-top:clamp(128px,11vw,170px)}
.mvwi-tail{position:relative;flex:1 1 0;min-height:0;display:flex;align-items:flex-end;justify-content:center;overflow:hidden;background:repeating-linear-gradient(180deg,transparent 0 120px,color-mix(in srgb,var(--mv-cloud) 5%,transparent) 120px 121px)} .mvwi-tail em{font:500 12px/1 var(--mv-font-m,'Chivo Mono'),ui-monospace,monospace;font-style:normal;letter-spacing:.14em;color:#F2923A;opacity:.85;padding:8px 0}
.mvwi-lane{position:absolute;top:0;bottom:0;width:var(--lane);background:#FFF1DA;-webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='22' height='26'><rect x='6' y='7' width='10' height='12' rx='2.5'/></svg>") center 0/22px 26px repeat-y;mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='22' height='26'><rect x='6' y='7' width='10' height='12' rx='2.5'/></svg>") center 0/22px 26px repeat-y;opacity:.92}
.mvwi-lane.is-l{left:0} .mvwi-lane.is-r{right:0}
.mvwi-cell{position:relative}
.mvwi-fr{--ex:1;position:relative;display:flex;flex-direction:column;gap:10px;padding-bottom:18px;text-decoration:none;color:inherit;outline-offset:4px;border-bottom:1px solid color-mix(in srgb,var(--mv-cloud) 7%,transparent)}
.mvwi.is-anim .mvwi-fr{--ex:0}
.mvwi-col .mvwi-cell:last-child .mvwi-fr{border-bottom:0;padding-bottom:6px}
.mvwi-edge{display:flex;justify-content:space-between;gap:12px;font:500 12px/1 var(--mv-font-m,'Chivo Mono'),ui-monospace,monospace;letter-spacing:.12em;color:#F2923A;opacity:calc(.8 + var(--ex) * .2)} .mvwi-edge em{font-style:normal}
.mvwi-win{position:relative;display:block;aspect-ratio:var(--ar,3/2);border-radius:2px;overflow:hidden;background:#1b1a18;isolation:isolate}
.mvwi-win img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block;scale:calc(1.07 - var(--ex) * .07);transition:scale .9s cubic-bezier(.2,.8,.2,1),filter .6s;user-select:none}
