.mvwi.is-ph .mvwi-rn{grid-area:n;align-self:start;padding-top:6px} .mvwi.is-ph .mvwi-rt{grid-area:t;font-size:30px} .mvwi.is-ph .mvwi-rc{grid-area:m;font-size:12px} .mvwi.is-ph .mvwi-rk,.mvwi.is-ph .mvwi-ry{display:none} .mvwi.is-ph .mvwi-ra{grid-area:a;width:34px;height:34px}
.mvwi.is-ph .mvwi-lp{display:none}
@media (hover:none){.mvwi-lp{display:none}}
@media (prefers-reduced-motion:reduce){.mvwi-fr,.mvwi-row{--ex:1!important} .mvwi-sw{display:none}}

